/*
    DVLD System - Reference / Seed Data

    Run this script AFTER 01_CreateSchema.sql.

    Target database: DVLD2

    Included:
      - Application statuses
      - Countries (250 reference records)
      - License classes
      - License issue reasons
      - Services
      - Active permissions used by the application
      - Core roles (Admin, Manager, Employee)
      - Role-to-permission mappings

    Intentionally excluded:
      - Persons, Users, Applications, Licenses and UserRoles:
        these are operational/demo records and are not included.
      - ArabCountries: the application code does not use this table.

    The script is designed to be re-runnable:
    existing IDs are not duplicated.
*/

USE [DVLD2];
GO

SET NOCOUNT ON;
SET XACT_ABORT ON;
GO

BEGIN TRY
    BEGIN TRANSACTION;

    /* 1. Application statuses */
    SET IDENTITY_INSERT dbo.ApplicationStatuses ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.ApplicationStatuses WHERE ApplicationStatusID = 1)
        INSERT dbo.ApplicationStatuses (ApplicationStatusID, StatusName) VALUES (1, N'New');
    IF NOT EXISTS (SELECT 1 FROM dbo.ApplicationStatuses WHERE ApplicationStatusID = 2)
        INSERT dbo.ApplicationStatuses (ApplicationStatusID, StatusName) VALUES (2, N'Cancelled');
    IF NOT EXISTS (SELECT 1 FROM dbo.ApplicationStatuses WHERE ApplicationStatusID = 3)
        INSERT dbo.ApplicationStatuses (ApplicationStatusID, StatusName) VALUES (3, N'Completed');
    SET IDENTITY_INSERT dbo.ApplicationStatuses OFF;

    /* 2. License classes */
    SET IDENTITY_INSERT dbo.LicenseClasses ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 1)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (1, N'Small Motorcycle', 18, 15.00, 5, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 2)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (2, N'Heavy Motorcycle', 21, 30.00, 5, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 3)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (3, N'Regular Car', 18, 20.00, 10, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 6)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (6, N'Commercial (Taxi/Limousine)', 21, 200.00, 10, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 11)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (11, N'Agricultural Vehicles', 21, 50.00, 10, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 12)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (12, N'Small/Medium Bus', 21, 250.00, 10, 1);
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseClasses WHERE LicenseClassID = 13)
        INSERT dbo.LicenseClasses (LicenseClassID, ClassName, MinimumAllowedAge, LicenseFees, DefaultValidityLength, IsActive)
        VALUES (13, N'Truck/Heavy Vehicle', 21, 300.00, 10, 1);
    SET IDENTITY_INSERT dbo.LicenseClasses OFF;

    /* 3. License issue reasons */
    SET IDENTITY_INSERT dbo.LicenseIssueReasons ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseIssueReasons WHERE ReasonID = 1)
        INSERT dbo.LicenseIssueReasons (ReasonID, ReasonName) VALUES (1, N'New');
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseIssueReasons WHERE ReasonID = 2)
        INSERT dbo.LicenseIssueReasons (ReasonID, ReasonName) VALUES (2, N'ReplacementForLost');
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseIssueReasons WHERE ReasonID = 3)
        INSERT dbo.LicenseIssueReasons (ReasonID, ReasonName) VALUES (3, N'ReplacementForDamaged');
    IF NOT EXISTS (SELECT 1 FROM dbo.LicenseIssueReasons WHERE ReasonID = 4)
        INSERT dbo.LicenseIssueReasons (ReasonID, ReasonName) VALUES (4, N'Renewal');
    SET IDENTITY_INSERT dbo.LicenseIssueReasons OFF;

    /* 4. Services */
    SET IDENTITY_INSERT dbo.Services ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 1)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (1, N'First-Time License Issuance', 5.55);
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 2)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (2, N'Renew-Test', 5.00);
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 3)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (3, N'Renew Driving License', 10.00);
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 4)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (4, N'Replacement for Lost License', 20.00);
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 5)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (5, N'Replacement for Damaged License', 20.00);
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 6)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (6, N'Release Driving License Hold', NULL);
    IF NOT EXISTS (SELECT 1 FROM dbo.Services WHERE ServiceID = 8)
        INSERT dbo.Services (ServiceID, ServiceName, ApplicationFees) VALUES (8, N'International License', 20.00);
    SET IDENTITY_INSERT dbo.Services OFF;

    /* 5. Active application permissions (IDs must match the C# enum) */
    SET IDENTITY_INSERT dbo.Permissions ON;
    DECLARE @Permissions TABLE
    (
        PermissionID int NOT NULL PRIMARY KEY,
        PermissionName nvarchar(250) NOT NULL,
        PermissionCategory nvarchar(250) NULL
    );
    INSERT INTO @Permissions (PermissionID, PermissionName, PermissionCategory) VALUES
      (1, N'ViewUsers', N'User'),
      (3, N'AddUserAndRole', N'User'),
      (5, N'UpdateUserLoginInfo', N'User'),
      (6, N'DeleteUsers', N'User'),
      (9, N'UpdateUserPassword', N'User'),
      (1009, N'RestoreUsers', N'User'),
      (1010, N'ViewPersons', N'Person'),
      (1011, N'ManageUsers', N'User'),
      (1013, N'UpdatePersons', N'Person'),
      (1014, N'ManagePersons', N'Person'),
      (1016, N'AddPersons', N'Person'),
      (1017, N'DeletePersons', N'Person'),
      (1018, N'RestorePersons', N'Person'),
      (1019, N'UpdateUserRoles', N'Role'),
      (1020, N'ViewUserRoles', N'Role'),
      (1021, N'ManageRoles', N'Role'),
      (1022, N'ViewRoles', N'Role'),
      (1023, N'AddRoleAndPermissions', N'Role'),
      (1027, N'UpdateRoleAndPermissions', N'Role'),
      (1028, N'DeleteRole', N'Role'),
      (1029, N'RestoreRole', N'Role'),
      (1030, N'ViewRolePermissions', N'Permissions'),
      (1032, N'ViewPermissions', N'Permissions'),
      (1033, N'AddPermissions', N'Permissions'),
      (1034, N'UpdatePermissions', N'Permissions'),
      (1035, N'DisablingPermissions', N'Permissions'),
      (1036, N'ActivePermissions', N'Permissions'),
      (1037, N'ManagePermissions', N'Permissions'),
      (1062, N'ManageApplicaations', N'Application'), -- Stored spelling in DB; C# enum uses ManageApplications with the same ID.
      (1063, N'ViewApplications', N'Application');

    INSERT dbo.Permissions (PermissionID, PermissionName, PermissionCategory, IsActive)
    SELECT P.PermissionID, P.PermissionName, P.PermissionCategory, 1
    FROM @Permissions P
    WHERE NOT EXISTS
    (
        SELECT 1 FROM dbo.Permissions Existing WHERE Existing.PermissionID = P.PermissionID
    );
    SET IDENTITY_INSERT dbo.Permissions OFF;

    /* 6. Core roles - no demo users or persons are created */
    SET IDENTITY_INSERT dbo.Roles ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleID = 1)
        INSERT dbo.Roles (RoleID, RoleName, Description, IsDeleted) VALUES (1, N'Admin', NULL, 0);
    IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleID = 2)
        INSERT dbo.Roles (RoleID, RoleName, Description, IsDeleted) VALUES (2, N'Manager', NULL, 0);
    IF NOT EXISTS (SELECT 1 FROM dbo.Roles WHERE RoleID = 3)
        INSERT dbo.Roles (RoleID, RoleName, Description, IsDeleted) VALUES (3, N'Employee', NULL, 0);
    SET IDENTITY_INSERT dbo.Roles OFF;

    /* 7. Role permissions: exact mappings verified from the development DB */
    INSERT dbo.RolePermissions (FK_RoleID, FK_PermissionID)
    SELECT 1, P.PermissionID
    FROM @Permissions P
    WHERE NOT EXISTS
    (
        SELECT 1 FROM dbo.RolePermissions RP
        WHERE RP.FK_RoleID = 1 AND RP.FK_PermissionID = P.PermissionID
    );

    INSERT dbo.RolePermissions (FK_RoleID, FK_PermissionID)
    SELECT 2, P.PermissionID
    FROM (VALUES (1010), (1014)) AS P(PermissionID)
    WHERE NOT EXISTS
    (
        SELECT 1 FROM dbo.RolePermissions RP
        WHERE RP.FK_RoleID = 2 AND RP.FK_PermissionID = P.PermissionID
    );

    IF NOT EXISTS (SELECT 1 FROM dbo.RolePermissions WHERE FK_RoleID = 3 AND FK_PermissionID = 1014)
        INSERT dbo.RolePermissions (FK_RoleID, FK_PermissionID) VALUES (3, 1014);

    -- Seed Countries
    SET IDENTITY_INSERT dbo.Countries ON;
    IF NOT EXISTS (SELECT 1 FROM dbo.Countries WHERE CountryID = 1)
        INSERT INTO dbo.Countries (CountryID, CountryName, CountryCode) VALUES (1, N'Afghanistan', N'AF');                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                              
